/** static u8 CalcMinHandDelta(u16 speed) */
export function CalcMinHandDelta(speed: any): any {
  if (speed > 60)
          return 6;
      if (speed > 30)
          return 3;
      if (speed > 10)
          return 2;

      return 1;
}

/** static u16 CalcNewMinHandAngle(u16 angle, u8 direction, u8 speed) */
export function CalcNewMinHandAngle(angle: any, direction: any, speed: any): any {
  let delta: any = CalcMinHandDelta(speed);
      switch (direction)
      {
      case MOVE_BACKWARD:
          if (angle)
              angle -= delta;
          else
              angle = 360 - delta;
          break;
      case MOVE_FORWARD:
          if (angle < 360 - delta)
              angle += delta;
          else
              angle = 0;
          break;
      }
      return angle;
}

/** static bool32 AdvanceClock(u8 taskId, u8 direction) */
export function AdvanceClock(taskId: any, direction: any): any {
  switch (direction)
      {
      case MOVE_BACKWARD:
          if (gTasks[taskId].tMinutes > 0)
          {
              gTasks[taskId].tMinutes--;
          }
          else
          {
              gTasks[taskId].tMinutes = 59;

              if (gTasks[taskId].tHours > 0)
                  gTasks[taskId].tHours--;
              else
                  gTasks[taskId].tHours = 23;

              UpdateClockPeriod(taskId, direction);
          }
          break;
      case MOVE_FORWARD:
          if (gTasks[taskId].tMinutes < 59)
          {
              gTasks[taskId].tMinutes++;
          }
          else
          {
              gTasks[taskId].tMinutes = 0;

              if (gTasks[taskId].tHours < 23)
                  gTasks[taskId].tHours++;
              else
                  gTasks[taskId].tHours = 0;

              UpdateClockPeriod(taskId, direction);
          }
          break;
      }
      return FALSE;
}

/** static void UpdateClockPeriod(u8 taskId, u8 direction) */
export function UpdateClockPeriod(taskId: any, direction: any): any {
  let hours: any = gTasks[taskId].tHours;
      switch (direction)
      {
      case MOVE_BACKWARD:
          switch (hours)
          {
          case 11:
              gTasks[taskId].tPeriod = PERIOD_AM;
              break;
          case 23:
              gTasks[taskId].tPeriod = PERIOD_PM;
              break;
          }
          break;
      case MOVE_FORWARD:
          switch (hours)
          {
          case 0:
              gTasks[taskId].tPeriod = PERIOD_AM;
              break;
          case 12:
              gTasks[taskId].tPeriod = PERIOD_PM;
              break;
          }
          break;
      }
}

/** static void InitClockWithRtc(u8 taskId) */
export function InitClockWithRtc(taskId: any): any {
  RtcCalcLocalTime();
      gTasks[taskId].tHours = gLocalTime.hours;
      gTasks[taskId].tMinutes = gLocalTime.minutes;
      gTasks[taskId].tMinuteHandAngle = gTasks[taskId].tMinutes * 6;
      gTasks[taskId].tHourHandAngle = (gTasks[taskId].tHours % 12) * 30 + (gTasks[taskId].tMinutes / 10) * 5;

      if (gLocalTime.hours < 12)
          gTasks[taskId].tPeriod = PERIOD_AM;
      else
          gTasks[taskId].tPeriod = PERIOD_PM;
}

/** static void SpriteCB_MinuteHand(struct Sprite *sprite) */
export function SpriteCB_MinuteHand(sprite: any): any {
  let angle: any = gTasks[sprite.sTaskId].tMinuteHandAngle;
      let sin: any = Sin2(angle) / 16;
      let cos: any = Cos2(angle) / 16;
      let x, y;

      SetOamMatrix(0, cos, sin, -sin, cos);
      x = sClockHandCoords[angle][0];
      y = sClockHandCoords[angle][1];

      if (x > 128)
          x |= 0xff00;
      if (y > 128)
          y |= 0xff00;

      sprite.x2 = x;
      sprite.y2 = y;
}

